INSERT INTO `products` (`product_id`, `user_id`, `name`, `description`, `price`, `stock`, `image`, `created_at`, `updated_at`) VALUES
                                                                                                                                   (28, 1, 'Lenovo  Lenovo Thinkbook Plus', 'The Lenovo ThinkBook Plus IRU Gen 4 is a unique dual screen laptop designed for professionals, creators, and multitaskers who want a more efficient and flexible workspace. With its innovative dual display setup, it enhances productivity by allowing you to manage multiple tasks, apps, and workflows at the same time.\r\n\r\nPowered by the Intel Core i5-1335U processor, this laptop delivers smooth and efficient performance for everyday productivity. It is well suited for office work, multitasking, content creation, and business applications. The processor ensures stable performance while maintaining power efficiency for daily use.\r\n\r\nWith 16GB RAM, the system provides seamless multitasking, allowing you to run multiple applications, manage large documents, and switch between tasks without slowdown. The 512GB SSD ensures fast boot times, quick file access, and reliable storage for important files, software, and media.', 135000.00, 15, 'static/images/productImage/1779091107597_Lenovo Thinkbook Plus.png', '2026-05-18 07:58:27', '2026-05-18 07:58:27'),
                                                                                                                                   (29, 1, 'Lenovo  Lenovo Thinkpad X13 Gen 6', 'Lenovo ThinkPad X13 Gen 6 Core Ultra 7 255H Laptop in Nepal\r\nThe Lenovo ThinkPad X13 Gen 6 is a premium ultra-portable business laptop designed for professionals who need power, portability, and reliability in one compact device. Powered by the latest Intel Core Ultra 7 255H processor, this laptop delivers exceptional performance for multitasking, office work, and demanding applications. Whether you are working remotely, in the office, or on the move, the ThinkPad X13 Gen 6 ensures smooth and efficient productivity.\r\n\r\nThis model comes with 32GB DDR5 RAM, allowing seamless multitasking and handling of heavy workloads without lag. The 512GB PCIe Gen 4 NVMe SSD provides ultra-fast storage speeds, ensuring quick boot times and fast data access. The 13.3-inch WUXGA (1920 x 1200) display offers sharp visuals, accurate colors, and an anti-glare panel, making it comfortable for long working hours.\r\n\r\nBuilt with the legendary ThinkPad durability, the X13 Gen 6 features a lightweight yet robust design, making it ideal for business users who travel frequently. The backlit ThinkPad keyboard ensures comfortable typing even in low-light environments, while Windows 11 Pro enhances security and productivity with advanced business features.', 312000.00, 20, 'static/images/productImage/1779091243596_Lenovo Thinkpad X13 Gen 6.png', '2026-05-18 08:00:43', '2026-05-18 08:00:43'),
                                                                                                                                   (30, 1, 'Apple  Apple MacBook Pro 14-inch M4 Pro ', 'Apple MacBook Pro 14-inch M4 Pro (2024) 24GB 512GB Price in Nepal\r\nLooking for the latest MacBook Pro price in Nepal? The Apple MacBook Pro 14-inch M4 Pro (2024) with 24GB unified memory and 512GB SSD is now available at ITTI Computer World with official warranty, VAT bill, EMI facility, and fast nationwide delivery. If you want to buy MacBook Pro in Nepal from a trusted retailer, ITTI offers competitive Apple laptop price in Nepal with reliable after-sales support.\r\n\r\nDesigned for professionals and creators, this MacBook Pro delivers outstanding performance, exceptional display quality, and long battery life—perfect for demanding workflows like coding, 4K video editing, graphic design, music production, and advanced multitasking.\r\n\r\nPowerful Performance with Apple M4 Pro Chip\r\nThe Apple M4 chip is built for speed and efficiency:\r\n\r\n12-Core CPU (6 Performance + 6 Efficiency cores) for smooth multitasking\r\n\r\n16-Core GPU for enhanced graphics and rendering\r\n\r\nAdvanced Neural Engine for AI-based workflows\r\n\r\nOptimized Apple Silicon architecture for sustained performance\r\n\r\nWhether you\'re working with professional software, compiling large projects, or editing high-resolution media files, the MacBook Pro 14-inch handles everything with ease.', 335000.00, 20, 'static/images/productImage/1779091345410_Apple MacBook Pro 14-inch M4 Pro.png', '2026-05-18 08:02:25', '2026-05-18 08:02:25'),
(31, 1, 'Asus  Asus Zenbook 14 UM3406KA', 'Asus Zenbook 14 UM3406KA – AI-Powered OLED Ultrabook for Everyday Performance\r\nThe Asus Zenbook 14 UM3406KA is a sleek and modern ultrabook designed for users who want reliable performance, premium visuals, and excellent portability in a compact device. Powered by the latest AMD Ryzen AI processor, this laptop is built to handle everyday computing, multitasking, and AI-enhanced workflows with ease. Its lightweight design makes it perfect for users who are always on the move, while the vibrant 3K OLED display delivers an immersive viewing experience for work, creativity, and entertainment. Whether you are a professional managing multiple tasks, a student attending online classes, or a creator working on visual projects, the Zenbook 14 offers a balanced combination of speed, efficiency, and style.\r\n\r\nSmart Performance with Ryzen AI\r\nEquipped with the AMD Ryzen AI 7 350 processor, the Zenbook 14 provides fast and efficient performance for modern workloads. It is optimized for multitasking, office applications, and AI-driven tasks, ensuring a smooth and responsive experience.\r\n\r\nWith 16GB RAM, you can run multiple applications and browser tabs without lag. The 1TB SSD delivers quick boot times, fast data access, and enough storage for your files, software, and media.\r\n\r\nStunning 14-inch 3K OLED Display\r\nThe 14-inch 3K OLED display offers exceptional clarity, vibrant colors, and deep contrast. It enhances both productivity and entertainment, making every task visually engaging.\r\n\r\nDisplay highlights:\r\n\r\n3K resolution for sharp and detailed visuals\r\n\r\nOLED panel with rich colors and deep blacks\r\n\r\nExcellent for content creation, streaming, and everyday use\r\n\r\nComfortable viewing for long working hours\r\n\r\nIntegrated Radeon Graphics\r\nThe integrated AMD Radeon Graphics provides reliable performance for everyday graphics tasks, multimedia use, and light creative workloads. It is ideal for users who need efficient graphics performance without a dedicated GPU.\r\n\r\nSlim, Lightweight, and Premium Design\r\nThe Zenbook 14 features a slim and lightweight build that is easy to carry, making it ideal for travel, office use, and study. Its premium design ensures durability while maintaining a clean and professional look.\r\n\r\nBuilt for Modern Productivity\r\nWith Windows 11, this laptop offers a smooth and user-friendly experience with enhanced productivity features. It is well suited for office work, remote meetings, browsing, and creative tasks.\r\n\r\nKey Features\r\nAMD Ryzen AI 7 350 processor for efficient performance\r\n\r\n16GB RAM for smooth multitasking\r\n\r\n1TB SSD for fast storage and quick access\r\n\r\n14-inch 3K OLED display\r\n\r\nAMD Radeon Graphics for everyday visual performance\r\n\r\nSlim and lightweight premium design\r\n\r\n2 years warranty for peace of mind', 210000.00, 20, 'static/images/productImage/1779091611039_Asus Zenbook 14 UM3406KA.png', '2026-05-18 08:06:51', '2026-05-18 08:06:51'),
(32, 1, 'Asus ASUS Zenbook Duo UX8406CA ', 'ASUS Zenbook Duo UX8406CA – Dual OLED Touchscreen Laptop for Ultimate Productivity\r\nThe ASUS Zenbook Duo UX8406CA is a next-generation dual-screen laptop designed for professionals, creators, and multitaskers who want more screen space, more flexibility, and more performance. Featuring two stunning 14-inch OLED touch displays, powerful Intel Core Ultra processing, and a premium portable design, this laptop transforms the way you work, create, and collaborate.\r\n\r\nDual 14-inch 3K OLED Touch Displays\r\nThe standout feature of the Zenbook Duo is its dual 14-inch 3K OLED touchscreens, offering an immersive and highly productive workspace. You can extend, mirror, or customize both displays to suit your workflow.\r\n\r\nDisplay advantages:\r\n\r\nDual 3K OLED panels with exceptional clarity and detail\r\n\r\n120Hz refresh rate for smooth visuals and responsiveness\r\n\r\nTouchscreen support for intuitive navigation and control\r\n\r\nIdeal for multitasking, coding, editing, designing, and streaming\r\n\r\nWhether you are editing timelines, managing multiple apps, or presenting content, the dual-screen setup enhances efficiency and creativity.\r\n\r\nPowerful Intel Core Ultra Performance\r\nPowered by the latest 15th Gen Intel Core Ultra 9 285H processor, this laptop delivers fast and intelligent performance for modern workloads. Combined with Intel Arc Graphics, it handles productivity tasks, creative applications, and light graphics work with ease.\r\n\r\nWith 32GB RAM, you can run multiple heavy applications simultaneously without lag. The 2TB Gen 4 SSD ensures ultra-fast storage, quick boot times, and ample space for large files and projects.\r\n\r\nDesigned for Creativity and Flexibility\r\nThe Zenbook Duo is built for dynamic workflows. It comes with a stylus, allowing you to sketch, take notes, and interact naturally with the touchscreen displays. This makes it perfect for designers, content creators, and professionals who prefer hands-on interaction.\r\n\r\nThe versatile design allows multiple usage modes, including laptop mode, dual-screen mode, and desktop-style setup, giving you flexibility in any environment.\r\n\r\nPremium Build with Portable Design\r\nFinished in Inkwell Grey, the Zenbook Duo offers a sleek and professional look. Despite its dual-screen setup, it remains portable and practical for everyday use, whether at home, in the office, or on the move.\r\n\r\nKey Features\r\nDual 14-inch 3K OLED 120Hz touchscreen displays\r\n\r\n15th Gen Intel Core Ultra 9 285H processor\r\n\r\nIntel Arc Graphics for smooth visual performance\r\n\r\n32GB RAM for advanced multitasking\r\n\r\n2TB Gen 4 SSD for fast and spacious storage\r\n\r\nStylus support for creative and professional use\r\n\r\nWindows 11 for modern productivity\r\n\r\nPremium design in Inkwell Grey\r\n\r\n2 Year international warranty with 1 Year perfect warranty\r\n\r\nWhy Buy ASUS Zenbook Duo UX8406CA from ITTI Computer World\r\nWhen investing in a premium laptop like the Zenbook Duo, choosing a trusted retailer is essential.\r\n\r\nAt ITTI Computer World, you get:\r\n\r\nGenuine ASUS products with official warranty coverage\r\n\r\nCompetitive pricing and best value in Nepal\r\n\r\nExpert support to help you choose and set up your device\r\n\r\nReliable after-sales service and technical assistance\r\n\r\nFast delivery and secure online shopping experience', 379000.00, 20, 'static/images/productImage/1779091699976_ASUS Zenbook Duo UX8406CA.png', '2026-05-18 08:08:19', '2026-05-18 08:08:19'),
(33, 1, 'Lenovo Lenovo Legion Pro 7i Gaming Laptop 2025', 'Lenovo Legion Pro 7i Gaming Laptop 2025 – Intel Core Ultra 9 275HX | RTX 5090\r\nIf you are looking for the ultimate flagship gaming laptop, the Lenovo Legion Pro 7i (2025) delivers extreme performance, cutting-edge graphics, and a premium OLED display designed for competitive gaming and professional workloads. Powered by the latest Intel Core Ultra 9 275HX processor and NVIDIA GeForce RTX 5090 GPU, this laptop provides desktop-level power in a portable form factor.\r\n\r\nAt ITTI Computer World, Nepal’s trusted destination for genuine gaming laptops, you can buy the Lenovo Legion Pro 7i 2025 with official warranty, authentic products, and reliable after-sales service.', 860000.00, 20, 'static/images/productImage/1779091795690_Lenovo Legion Pro 7i Gaming Laptop 2025.png', '2026-05-18 08:09:55', '2026-05-18 08:09:55'),
(34, 1, 'Acer  Acer Predator Helios 18 ', 'Acer Predator Helios 18 AI Price in Nepal – Core Ultra 9 275HX, RTX 5090, 96GB RAM\r\nThe Acer Predator Helios 18 AI is the ultimate flagship gaming laptop built for extreme performance, next-generation AI workloads, and professional-grade computing. Designed as a true desktop replacement, this powerhouse combines cutting-edge hardware with a massive display, making it ideal for gamers, creators, developers, and AI professionals in Nepal.\r\n\r\nAt its core, the laptop is powered by the Intel Core Ultra 9 275HX processor, delivering exceptional multi-core performance with advanced hybrid architecture. Whether you are running heavy simulations, rendering complex 3D scenes, or multitasking across demanding applications, this processor ensures smooth and efficient performance.\r\n\r\nFor graphics, the Helios 18 AI features the NVIDIA GeForce RTX 5090 with 24GB GDDR7 VRAM, offering unmatched GPU performance. Built for 4K gaming, real-time ray tracing, DLSS 4, and AI acceleration, it can handle the most demanding AAA titles, game development engines, machine learning workloads, and professional creative software with ease.\r\n\r\nThe laptop boasts a massive 18-inch WQUXGA IPS display (3840 x 2400), delivering ultra-sharp visuals, accurate color reproduction, and an immersive viewing experience. Whether you are gaming, editing videos, or designing, the large high-resolution panel provides exceptional clarity and workspace.\r\n\r\nEquipped with an incredible 96GB DDR5 RAM running at 6400MHz, this system offers unmatched multitasking capability. You can run multiple heavy applications, virtual machines, and AI workloads simultaneously without slowdown. The 2TB PCIe Gen4 NVMe SSD ensures lightning-fast boot times, rapid file access, and massive storage capacity for games, software, and large projects.\r\n\r\nCooling is handled by Acer’s advanced Predator thermal system, designed to maintain peak performance even under extreme workloads. Combined with a premium chassis, RGB backlit keyboard, and robust build quality, the Helios 18 AI is engineered for both durability and performance.\r\n\r\nWith AI-enhanced performance tuning, DLSS 4, and Advanced Optimus, this laptop is fully prepared for the future of gaming and productivity.', 940000.00, 20, 'static/images/productImage/1779091952850_Acer Predator Helios 18 AI Intel Core Ultra 9 275HX.png', '2026-05-18 08:12:32', '2026-05-18 08:12:32'),
(35, 1, 'ASUS Asus TUF A15 2024 FA506NFR', 'Brand new factory-sealed Asus TUF A15 2023 FA506NFR Gaming Laptop with 7000-series AMD Ryzen 7 7435HS processor featuring octa-core (8-core) CPU, NVIDIA GeForce RTX 2050 Graphics card with 4GB of GDDR6 VRAM (Supports Ray-tracing and DLSS), 8GB DDR5 RAM (Expandable up to 32GB),512GB SSD storage, 15.6-inch IPS display with Full-HD (1920 x 1080 pixels) resolution, 144Hz refresh rate, and Adaptive-Sync, 48 WHr Battery, Stereo speakers with DTS audio, 0.78-inch thickness, 2KG Weight, Backlit Keyboard, Free Asus TUF Original Gaming Backpack and Gaming Mouse, 2 Years of Warranty\r\n\r\n ', 130000.00, 15, 'static/images/productImage/1779092312782_Screenshot 2026-05-18 140314.png', '2026-05-18 08:18:32', '2026-05-18 08:18:32'),
(36, 1, 'Acer Acer Predator Triton 500', 'Acer Predator Triton 500 2020 10th Gen Core i7-10875H, RTX 2070 8GB, 15.6\" Full-HD 144Hz display 16GB RAM, 512GB SSD', 130000.00, 12, 'static/images/productImage/1779092424879_Screenshot 2026-05-18 140459.png', '2026-05-18 08:20:24', '2026-05-18 08:20:24'),
(37, 1, 'Acer  Acer Predator Triton 300 2020', 'Acer Predator Triton 300 2020 10th Gen Core i7-10750H, RTX 2060, 15.6\" Full-HD 144Hz display 16GB RAM, 512GB SSD', 109000.00, 12, 'static/images/productImage/1779092520591_Screenshot 2026-05-18 140638.png', '2026-05-18 08:22:00', '2026-05-18 08:22:00'),
                                                                                                                                    (38, 1, 'Lenovo  Lenovo Legion 5 Pro 2021', 'The Lenovo Legion 5 Pro 2021 is a powerful gaming laptop designed for gamers, creators, and professionals who need high performance and immersive visuals. Powered by the AMD Ryzen 7 5800H processor and NVIDIA GeForce RTX 3060 graphics, this laptop delivers excellent performance for modern AAA gaming, content creation, and multitasking workloads.\r\n\r\nAt the heart of the system is the AMD Ryzen 7 5800H processor, an 8-core and 16-thread CPU capable of boosting up to around 4.4 GHz, providing strong performance for gaming, streaming, video editing, and other demanding tasks.\r\n\r\nThe laptop comes equipped with 16GB DDR4 RAM, ensuring smooth multitasking and responsive performance even when running multiple applications. Combined with a 1TB PCIe NVMe SSD, users benefit from fast boot times, quick game loading, and ample storage for large game libraries and professional software.\r\n\r\nOne of the standout features of the Legion 5 Pro is its 16-inch WQXGA (2560 × 1600) display with a 165Hz refresh rate and 16:10 aspect ratio, delivering sharp visuals, vibrant colors, and ultra-smooth gameplay. This high-resolution display also provides better screen space for gaming and productivity.\r\n\r\nFor graphics performance, the NVIDIA GeForce RTX 3060 GPU with 6GB GDDR6 VRAM offers advanced ray tracing and AI-powered technologies such as DLSS, allowing modern games to run smoothly with enhanced realism and higher frame rates.\r\n\r\nThe laptop also features Legion ColdFront cooling technology, helping maintain stable performance during intense gaming sessions. With its RGB backlit keyboard, premium design, and powerful hardware, the Legion 5 Pro remains one of the most popular gaming laptops in its class.\r\n\r\nBuying from ITTI Computer World ensures that you receive genuine products, reliable warranty support, and trusted after-sales service in Nepal.', 135000.00, 20, 'static/images/productImage/1779092663847_Screenshot 2026-05-18 140910.png', '2026-05-18 08:24:23', '2026-05-18 08:24:23'),
                                                                                                                                    (39, 1, 'Dell Dell G5 G5510 2021', 'Brand new Dell G5 G5510 2021 Gaming laptop with 10th Gen Intel Core i7-10870H processor with Octa-core (8-core) CPU, NVIDIA RTX 3060 graphics card with 6GB of VRAM, 16GB DDR4 RAM (Expandable), 512GB SSD storage (Additional slot for storage expansion), 15.6-inch IPS display with 165Hz refresh rate, Full-HD resolution & 300 nits brightness, 2 x 2W stereo speakers, HD Web camera, RGB Backlight Keyboard, 0.83\" thickness, 2.44KG Weight', 108000.00, 19, 'static/images/productImage/1779092750492_Screenshot 2026-05-18 141036.png', '2026-05-18 08:25:50', '2026-05-18 08:25:50'),
                                                                                                                                    (40, 1, 'HP  HP Victus 16 2021', 'Brand new factory-sealed HP Victus 16 2021 Gaming Laptop with Intel Core i7-11800H processor featuring Octa-core (8-core) CPU, NVIDIA RTX 3060 Graphics Card with 6GB of GDDR6 VRAM, 512GB SSD Storage, 16GB DDR4 RAM (Expandable up to 32GB), 16.1-inch IPS display with 144Hz Full-HD (1920 x 1080 pixels) resolution, Bang & Olufsen-tuned Dual speakers, Up to 5 hours of battery life, HD (720p) Webcam, Backlit Keyboard.', 125000.00, 18, 'static/images/productImage/1779092849399_Screenshot 2026-05-18 141212.png', '2026-05-18 08:27:29', '2026-05-18 08:27:29'),
                                                                                                                                    (41, 1, 'Dell Dell Dell XPS 15 9500', 'Brand new factory-sealed Dell XPS 15 9500 2020 with 10th Gen Intel Core i7-10750H processor featuring Hexa-core (6-core) CPU, NVIDIA GeForce GTX 1650Ti Graphics Card with 4GB of GDDR6 VRAM, 16GB DDR4 RAM (Expandable up to 32GB), 1TB PCIe SSD storage, 15.6-inch InfinityEdge Non-touch Anti-glare display with Full-HD (1920 x 1200 pixels) resolution, 500 nits brightness, 86Wh battery with remarkable battery backup, Stereo speakers, Backlit Keyboard. Comes with free laptop bag and mouse, ITTI Computer World offers 1 Year Warranty and free delivery all over Nepal', 245000.00, 17, 'static/images/productImage/1779093008760_Screenshot 2026-05-18 141406.png', '2026-05-18 08:29:18', '2026-05-18 08:30:08'),
                                                                                                                                    (42, 1, 'Acer  Acer Spin 3 2021', 'The Acer Spin 3 2021 (SP513-51N) is a versatile 2-in-1 convertible laptop designed for users who need flexibility, portability, and solid everyday performance. With its 360-degree hinge, this device easily transforms between laptop, tablet, tent, and stand modes, making it ideal for students, professionals, and creative users.\r\n\r\nPowered by the 11th Gen Intel Core i7-1165G7 processor, the Spin 3 delivers reliable performance for multitasking, office work, online learning, and light creative tasks. The processor is paired with 8GB LPDDR4x RAM, ensuring smooth operation for daily applications, browsing, and productivity workloads.\r\n\r\nThe laptop comes with a 512GB NVMe SSD, offering fast boot times, quick application loading, and ample storage for files, documents, and media.\r\n\r\nOne of the standout features is its 14-inch WQXGA (2560 x 1600) IPS touchscreen display, providing sharp visuals, vibrant colors, and excellent clarity. The 16:10 aspect ratio gives more vertical workspace, making it ideal for productivity and reading. The included rechargeable stylus allows precise note-taking, sketching, and interactive use.\r\n\r\nFor added convenience and security, the laptop includes a fingerprint reader for quick login and a backlit keyboard for comfortable typing in low-light environments. The Windows 10 optimized webcam ensures clear video calls for meetings and online classes.\r\n\r\nDespite its powerful features, the Spin 3 remains portable with a slim 0.63-inch thickness and a weight of approximately 3.3 lbs (around 1.5 kg), making it easy to carry for work or study.\r\n\r\nThis model is brand new and factory sealed, and comes with a free laptop bag and mouse, 1-year warranty, and free delivery all over Nepal, making it a complete and value-packed package.', 105000.00, 16, 'static/images/productImage/1779093088450_Screenshot 2026-05-18 141617.png', '2026-05-18 08:31:28', '2026-05-18 08:31:28'),
                                                                                                                                    (43, 1, 'ASUS Asus  VivoBook 15 K513EQ-BQ074T', 'Looking for a stylish, powerful, and reliable laptop in Nepal for office work, study, and everyday multitasking? The Asus VivoBook 15 K513EA-BQ388T is a well-balanced notebook that combines modern performance, premium features, and a sleek design, making it an excellent choice for students and professionals alike.\r\n\r\nPowered by the 11th Gen Intel Core i5-1135G7 processor, this laptop delivers strong performance for everyday computing tasks. Whether you\'re working on documents, attending online meetings, browsing with multiple tabs, or streaming content, it ensures smooth and efficient operation. The processor also supports Intel Iris Xe Graphics, which provides better visual performance for light editing, multimedia tasks, and casual gaming compared to older integrated graphics.\r\n\r\nWith 8GB DDR4 RAM, the system offers reliable multitasking performance, allowing you to run multiple applications simultaneously without lag. The 512GB SSD storage significantly enhances speed, ensuring faster boot times, quick file access, and smooth overall system responsiveness.\r\n\r\nThe laptop features a 15.6-inch Full HD LED-backlit display, delivering clear visuals and comfortable viewing angles for both work and entertainment. The anti-glare panel helps reduce reflections, making it suitable for long hours of usage. Its slim-bezel design enhances screen space, improving productivity and viewing experience.\r\n\r\nIn terms of design, the VivoBook K513EA stands out with its sleek and modern look, lightweight build of around 1.7KG, and slim 17.9mm thickness, making it easy to carry for daily use. It also includes a backlit keyboard, allowing you to work comfortably even in low-light environments, along with a fingerprint scanner for quick and secure login using Windows Hello.\r\n\r\nAdditional features such as WiFi 6 connectivity, USB Type-C, HDMI, and multiple USB ports ensure seamless connectivity for all your devices and accessories.\r\n\r\nAvailable at ITTI Computer World, this laptop is a perfect choice for students, office users, and professionals who want a balance of performance, style, and security. With 2 years warranty, free backpack, free mouse, and nationwide delivery, it offers a complete value package backed by trusted after-sales support.\r\n\r\nIf you are searching for a mid-range laptop in Nepal with strong performance and premium features, the Asus VivoBook 15 K513EA-BQ388T is one of the best options in its segment.', 85000.00, 18, 'static/images/productImage/1779093191599_Screenshot 2026-05-18 141759.png', '2026-05-18 08:33:11', '2026-05-18 08:33:11'),
(44, 1, 'Apple Apple M1 MacBook Air 2020', 'Experience power, efficiency, and premium Apple design with the Apple M1 MacBook Air 13.3-inch — now available at ITTI Computer World with Authorised Warranty in Nepal.\r\n\r\nDesigned with Apple’s revolutionary M1 chip, this MacBook Air delivers outstanding performance while remaining completely silent thanks to its fanless design. Whether you are a student, business professional, content creator, or everyday user, the M1 MacBook Air offers smooth multitasking, long battery life, and exceptional display quality.', 104000.00, 19, 'static/images/productImage/1779093277693_Screenshot 2026-05-18 141926.png', '2026-05-18 08:34:37', '2026-05-18 08:34:37'),
(45, 1, 'HP HP Omen 16 2024', 'Brand new, genuine, and factory-sealed HP Omen 16 2024  Gaming laptop with 14th Gen Intel Core i7-14650HX processor featuring SIXTEEN-core (16-core) CPU and 24 threads, NVIDIA RTX 4060 Graphics Card with 8GB of GDDR6 VRAM, 16GB DDR5 RAM (Expandable up to 32GB), 512GB SSD storage, 16.1-inch IPS display with FHD (1920 x 1080 pixels) resolution, 144Hz refresh rate, 3ms response time, 300 nits brightness, 100% sRGB color gamut (Color coverage close to 72% NTSC), Windows 11 Home Operating System, 83Wh battery with up to 6 hours of battery backup, Bang & Olufsen-powered stereo speakers with DTS:X Ultra and HP Audio Boost, HD (720p) WebCam with integrated dual array digital microphones, 2.3cm thickness, 2.3KG Weight, Mica Silver Color, Backlit Keyboard', 199000.00, 14, 'static/images/productImage/1779093378807_Screenshot 2026-05-18 142107.png', '2026-05-18 08:36:18', '2026-05-18 08:36:18'),
(46, 1, 'Dell Dell XPS 14 9440 2024', 'Dell’s New XPS Lineup: Futuristic Design, with Built-in AI', 425000.00, 19, 'static/images/productImage/1779093532559_Screenshot 2026-05-18 142339.png', '2026-05-18 08:38:52', '2026-05-18 08:38:52'),
(47, 1, 'ASUS Asus ROG Strix G16 2026 ', 'Upgrade your gaming setup and creative workflow with the ASUS ROG Strix G16 (2026) G615, a next-generation gaming laptop now available at ITTI Computer World Pvt. Ltd., Nepal’s trusted destination for genuine gaming laptops and premium PC hardware.\r\n\r\nDesigned for gamers, streamers, creators, and power users, the ROG Strix G16 (2026) combines cutting-edge performance with advanced cooling and a stunning high-refresh display. At its core is the powerful Intel Core Ultra 9 275HX processor, delivering high multi-core performance and AI acceleration for modern applications, multitasking, and heavy workloads.\r\n\r\nPaired with the NVIDIA GeForce RTX 5070 Ti Laptop GPU, this machine delivers exceptional performance in modern AAA games, competitive esports titles, and demanding creative tasks such as video editing, 3D rendering, and streaming.\r\n\r\nThe laptop features a 16-inch WQXGA (2560 × 1600) 240Hz display, providing ultra-smooth gameplay and sharp visuals. The high refresh rate ensures fluid motion during fast-paced gaming while the high resolution offers crisp detail for immersive gameplay and creative work.\r\n\r\nWith 16GB DDR5 RAM and a 1TB NVMe SSD, the ROG Strix G16 offers fast system responsiveness, rapid boot times, quick game loading, and ample storage for your games, files, and creative projects. Combined with the signature ROG gaming design, advanced cooling system, and RGB lighting, this laptop is built to maintain peak performance even during long gaming sessions.\r\n\r\nBuy the ASUS ROG Strix G16 (2026) G615 in Nepal from ITTI Computer World and enjoy genuine products, official warranty support, and reliable after-sales service', 420000.00, 9, 'static/images/productImage/1779093684521_Screenshot 2026-05-18 142602.png', '2026-05-18 08:41:24', '2026-05-18 08:41:24'),
(48, 1, 'Lenovo Intel Core Ultra 9 275HX', 'The Lenovo Legion Pro 7i Gaming Laptop 2025 is one of the most powerful gaming laptops available, designed for serious gamers, streamers, and creators who demand elite performance. Powered by the latest Intel Core Ultra 9 275HX processor and NVIDIA GeForce RTX 5080 graphics, this premium machine delivers desktop-level gaming power in a portable design.\r\n\r\nWhether you\'re playing demanding AAA games, editing high-resolution video, streaming live content, or running heavy creative workloads, the Legion Pro 7i provides exceptional speed, smooth graphics, and reliable multitasking performance.\r\n\r\nAt the core of this gaming powerhouse is the 24-core Intel Core Ultra 9 275HX processor, capable of boosting up to 5.4GHz, paired with 32GB DDR5 RAM and a fast 1TB NVMe SSD for lightning-fast load times and seamless multitasking.\r\n\r\nFor graphics performance, the laptop features the NVIDIA GeForce RTX 5080 Laptop GPU with 16GB GDDR7 VRAM, delivering advanced ray tracing, AI-accelerated rendering, and ultra-smooth gaming performance in modern titles.\r\n\r\nThe stunning 16-inch WQXGA OLED display with 240Hz refresh rate brings games and content to life with incredible clarity, vibrant colors, and ultra-smooth motion—perfect for competitive gaming and immersive visuals.\r\n\r\nLenovo’s advanced Legion ColdFront cooling system keeps the system stable even during intense gaming sessions, while the per-key RGB keyboard adds customizable style for your gaming setup.\r\n\r\nWith Wi-Fi 7 connectivity, premium speakers tuned with Nahimic Audio, and a sleek Eclipse Black design, the Legion Pro 7i is built for gamers who want uncompromising performance and premium build quality.', 545000.00, 17, 'static/images/productImage/1779093769403_Screenshot 2026-05-18 142735.png', '2026-05-18 08:42:49', '2026-05-18 08:42:49'),
                                                                                                                                    (49, 1, 'Dell  Intel® Core™ Ultra 9 Processor 275HX (14th Gen, high performance)', 'Dell Alienware Aurora 16X GAMING Ultra  9 275HX | 2TB SSD | 32GB RAM | 16\" (2560x1600) 240Hz | WIN11 |  NVIDIA RTX 5070 8192MB | BLUE Backlit Keyboard', 375000.00, 12, 'static/images/productImage/1779093837675_Screenshot 2026-05-18 142843.png', '2026-05-18 08:43:57', '2026-05-18 08:43:57'),
                                                                                                                                    (50, 1, 'ASUS Intel® Core™ Ultra 9 Processor 285H', 'The ASUS Zenbook Duo UX8406CA is a next-generation dual-screen laptop designed for professionals, creators, and multitaskers who want more screen space, more flexibility, and more performance. Featuring two stunning 14-inch OLED touch displays, powerful Intel Core Ultra processing, and a premium portable design, this laptop transforms the way you work, create, and collaborate.', 379000.00, 13, 'static/images/productImage/1779093925439_Screenshot 2026-05-18 143011.png', '2026-05-18 08:45:25', '2026-05-18 08:45:25'),
                                                                                                                                    (51, 1, 'Dell XPS 13 9350', 'Create and work anywhere with our thinnest XPS.\r\nA Copilot+ PC, powered by the Intel® Core™ Ultra processors Series 2, with more powerful AI', 361500.00, 16, 'static/images/productImage/1779093999578_Screenshot 2026-05-18 143127.png', '2026-05-18 08:46:39', '2026-05-18 08:46:39'),
                                                                                                                                    (52, 1, 'ASUS Asus ROG Strix G18 2023 G614JIR', 'The ASUS ROG Strix G18 2024 (G618JIR) is a powerful large-screen gaming laptop built for gamers, creators, and professionals who demand top-tier performance. Powered by the Intel Core i9-14900HX processor and NVIDIA GeForce RTX 4070 graphics, this laptop delivers excellent performance for AAA gaming, video editing, 3D rendering, streaming, and heavy multitasking.\r\n\r\nThe laptop features a large 18-inch WQXGA (2560 × 1600) display with a 240Hz refresh rate, providing ultra-smooth gameplay, sharp visuals, and an immersive viewing experience. The larger display enhances gaming, creative work, and productivity by offering more screen space and better visual clarity.\r\n\r\nWith 16GB DDR5 RAM and a 512GB NVMe SSD, the ROG Strix G18 ensures fast system performance, quick boot times, and responsive multitasking. ASUS ROG’s advanced cooling system, customizable RGB keyboard lighting, and durable premium design help maintain stable performance even during long gaming sessions.\r\n\r\n', 360000.00, 19, 'static/images/productImage/1779094068722_Screenshot 2026-05-18 143238.png', '2026-05-18 08:47:48', '2026-05-18 08:47:48'),
                                                                                                                                    (53, 1, 'ASUS AMD Ryzen™ 9 8940HX', 'The ASUS ROG Strix Scar G16 G614PM is a premium gaming laptop designed for gamers, creators, and power users who require high-end performance and smooth visuals. Powered by the AMD Ryzen 9 8940HX processor and NVIDIA GeForce RTX 5060 graphics, this laptop delivers excellent performance for modern AAA gaming, streaming, content creation, and demanding professional workloads.\r\n\r\nThe laptop features a 16-inch WQXGA (2560 × 1600) display with a 240Hz refresh rate, offering ultra-smooth gameplay, sharp detail, and immersive visuals. Whether you are playing competitive esports titles or working on creative projects, the high-resolution display ensures excellent clarity and responsiveness.\r\n\r\nWith 16GB DDR5 RAM and a 1TB NVMe SSD, the ROG Strix Scar G16 provides fast system performance, quick boot times, and sufficient storage for games, software, and professional applications. The laptop also includes ROG advanced cooling technology, customizable RGB lighting, and a durable premium design, ensuring reliable performance even during long gaming sessions.', 357000.00, 11, 'static/images/productImage/1779094143286_Screenshot 2026-05-18 143351.png', '2026-05-18 08:49:03', '2026-05-18 08:49:03'),
                                                                                                                                    (54, 1, 'MSI MSI Vector GP68 HX 13VG  2023 ', 'General\r\nBrand	MSI\r\nModel	Vector GP68 HX 13VG\r\nType	Gaming Laptop\r\nOperating System	Windows 11 Home\r\nRelease Year	2023\r\nProcessor & Graphics\r\nProcessor	13th Gen Intel Core i9-13950HX (24 Cores, up to 5.5GHz, 36MB Cache)\r\nGraphics	NVIDIA GeForce RTX 4070 Laptop GPU, 8GB GDDR6 (High TGP)\r\nDisplay\r\nDisplay Size	16-inch QHD (2560 x 1600), IPS-Level\r\nRefresh Rate	240Hz\r\nAspect Ratio	16:10\r\nMemory\r\nRAM	32GB DDR5 (Upgradable up to 64GB)\r\nMemory Slots	2 x SO-DIMM Slots\r\nStorage\r\nStorage	2TB NVMe PCIe Gen4 SSD\r\nStorage Slot	2x M.2 SSD Slots\r\nAudio & Camera\r\nSpeakers	Dual Speakers\r\nCamera	FHD 1080p Webcam\r\nConnectivity\r\nWiFi	WiFi 6E\r\nBluetooth	Bluetooth 5.3\r\nLAN	2.5G Ethernet\r\nPorts\r\nUSB Type-A	3 x USB 3.2 Gen1', 347700.00, 10, 'static/images/productImage/1779094228806_Screenshot 2026-05-18 143518.png', '2026-05-18 08:50:28', '2026-05-18 08:50:28'),
                                                                                                                                    (55, 1, 'MSI  MSI VECTOR 16 HX AI A2XWHG', 'The MSI Vector 16 HX AI A2XWHG is a flagship gaming laptop designed for professionals, gamers, and creators who need extreme performance and next-generation AI capabilities. Powered by the Intel Core Ultra 9 275HX processor and NVIDIA GeForce RTX 5070 Ti graphics, this laptop delivers outstanding speed, high FPS gaming, and powerful multitasking for demanding workloads.\r\n\r\nIt features a 16-inch QHD display with a 240Hz refresh rate, offering ultra-smooth visuals and exceptional clarity. The high refresh rate makes it ideal for competitive gaming, while the larger screen enhances productivity and immersive viewing experiences.\r\n\r\nWith 16GB DDR5 RAM and a 1TB NVMe SSD, the MSI Vector 16 HX AI ensures fast system performance, quick load times, and ample storage for games, creative projects, and professional applications. The system is upgrade-friendly, making it suitable for long-term use.\r\n\r\nThe NVIDIA RTX 5070 Ti GPU brings advanced ray tracing and AI-powered performance, enabling high-end gaming, video editing, 3D rendering, and AI workloads. Combined with MSI’s advanced cooling system, the laptop maintains stable performance even during intensive usage.\r\n\r\nOverall, the MSI Vector 16 HX AI is a premium gaming laptop in Nepal, offering top-tier performance, a high refresh rate display, and cutting-edge hardware for gaming, streaming, and professional use.', 345000.00, 13, 'static/images/productImage/1779094336943_Screenshot 2026-05-18 143704.png', '2026-05-18 08:52:16', '2026-05-18 08:52:16'),
                                                                                                                                    (56, 1, 'Dell  XPS 13 9350 2025 - 15th Gen Intel Core Ultra 7 256V', 'Dell XPS 13 9350 2025 (15th Gen Intel Core Ultra 7 256V Processor | 16GB RAM | 512GB SSD Storage | 13.4\" FHD+ (1920 x 1200) 120Hz 100% sRGB Infinity Edge Display | Intel Arc Graphics | Backlit Keyboard | Windows 11 Home | 2 Year Warranty)', 334000.00, 14, 'static/images/productImage/1779094459601_Screenshot 2026-05-18 143908.png', '2026-05-18 08:54:19', '2026-05-18 08:54:19'),
                                                                                                                                    (57, 1, 'Acer  Intel® Core™ Ultra 9 275HX (24 cores: 8 Performance + 16 Efficiency), up to 5.4 GHz turbo', 'The Acer Predator Helios Neo 16S AI 2025 is a flagship-level gaming laptop built for users who demand extreme performance, cutting-edge AI capabilities, and a premium visual experience. Powered by the Intel Core Ultra 9 275HX processor, this laptop delivers top-tier processing power with advanced hybrid architecture, making it ideal for high-end gaming, content creation, AI workloads, and heavy multitasking.\r\n\r\nFor graphics, it features the powerful NVIDIA GeForce RTX 5070 Ti GPU, offering next-generation performance with support for real-time ray tracing, DLSS 4, and AI acceleration. This ensures ultra-smooth gameplay in modern AAA titles, faster rendering speeds, and enhanced efficiency for creative and professional applications.\r\n\r\nThe laptop comes with 16GB DDR5 RAM, delivering smooth multitasking and responsive performance across applications. It is upgradeable, allowing users to expand memory for future needs. Storage is handled by a 1TB PCIe Gen 4 SSD, ensuring lightning-fast boot times, quick data access, and ample storage space for games and files.\r\n\r\nOne of the biggest highlights is its 16-inch OLED WQXGA (2560 x 1600) display with a 240Hz refresh rate, offering stunning visuals with deep blacks, vibrant colors, and ultra-smooth motion. The OLED panel significantly enhances gaming and content creation experiences with superior contrast and color accuracy.\r\n\r\nCooling is managed by advanced AeroBlade fan technology, ensuring stable performance even during extended gaming sessions or heavy workloads. The laptop also features a premium Predator design, RGB backlit keyboard, and a full range of modern connectivity options including Thunderbolt 4, HDMI 2.1, USB ports, and Ethernet.\r\n\r\nWith a 3-year warranty, this model provides long-term reliability and peace of mind, making it one of the best high-end gaming laptops available in Nepal for 2025.', 330000.00, 17, 'static/images/productImage/1779094526188_Screenshot 2026-05-18 144016.png', '2026-05-18 08:55:26', '2026-05-18 08:55:26'),
                                                                                                                                    (58, 1, 'Lenovo AMD Ryzen 7 260', 'The Lenovo Legion 5 Gaming Laptop 2025 is a powerful mid-range gaming laptop built for gamers, creators, and performance users who need reliable hardware and a premium display. Equipped with the AMD Ryzen 7 260 processor and NVIDIA GeForce RTX 5050 Laptop GPU, this laptop delivers smooth gameplay, fast multitasking, and excellent graphics performance for modern workloads.\r\n\r\nAt its core, the AMD Ryzen 7 260 processor features 8 cores and 16 threads with boost speeds up to around 5.1 GHz, providing strong performance for gaming, streaming, and demanding creative applications.\r\n\r\nThe Legion 5 comes with 16GB DDR5 RAM, allowing smooth multitasking and efficient handling of multiple applications at once. Combined with a 512GB PCIe Gen4 NVMe SSD, the system offers fast boot times, quick application launches, and responsive overall performance.\r\n\r\nOne of the key highlights of the laptop is its 15.1-inch WQXGA OLED display (2560 × 1600 resolution). The panel offers vibrant colors, deep contrast, and a 165Hz refresh rate, providing ultra-smooth visuals and immersive gameplay. The display also supports 100% DCI-P3 color gamut and HDR technologies, making it ideal for gaming and creative work.\r\n\r\nFor graphics performance, the NVIDIA GeForce RTX 5050 Laptop GPU with 8GB GDDR7 VRAM supports advanced ray tracing and AI-powered technologies like DLSS, delivering improved realism and higher frame rates in modern AAA titles.\r\n\r\nThe laptop also features Lenovo Legion ColdFront cooling, an RGB backlit keyboard, and a sleek Eclipse Black design that gives it a premium gaming look. With Windows 11 pre-installed, the Legion 5 is ready for gaming, productivity, and entertainment right out of the box.', 330000.00, 13, 'static/images/productImage/1779094610881_Screenshot 2026-05-18 144136.png', '2026-05-18 08:56:50', '2026-05-18 08:56:50'),
                                                                                                                                    (59, 1, 'Acer   Predator Helios Neo 16S AI 2025', 'The Acer Predator Helios Neo 16S AI is a flagship-level gaming laptop built for users who demand extreme performance, advanced AI capabilities, and a premium visual experience. Powered by the Intel Core Ultra 9 275HX processor, this laptop delivers top-tier performance with a powerful hybrid architecture, making it ideal for high-end gaming, professional content creation, and AI-driven workloads.\r\n\r\nAt the heart of its graphics performance is the NVIDIA GeForce RTX 5070 GPU, offering next-generation power with support for real-time ray tracing, DLSS 4, and advanced AI acceleration. This ensures ultra-smooth gameplay in modern AAA titles, faster rendering speeds, and improved efficiency for demanding creative applications.\r\n\r\nThe laptop features a stunning 16-inch OLED WQXGA (2560 x 1600) display with a 240Hz refresh rate, delivering exceptional color accuracy, deep contrast, and fluid motion. The OLED panel enhances visual quality with richer blacks and vibrant colors, while the high refresh rate ensures a competitive edge in fast-paced gaming.\r\n\r\nEquipped with 32GB DDR5 RAM running at 6500MHz, the system handles heavy multitasking, large-scale projects, and professional workloads effortlessly. The 1TB PCIe Gen 4 SSD ensures lightning-fast boot times, rapid file access, and ample storage for games, media, and applications.\r\n\r\nCooling is handled by 5th Gen AeroBlade fan technology, which maintains optimal temperatures and stable performance even during extended gaming sessions or intensive workloads. The laptop also features a premium chassis design, RGB backlit keyboard, and comprehensive connectivity options including Thunderbolt 4, HDMI 2.1, USB ports, and Ethernet.\r\n\r\nWith advanced AI features such as DLSS 4, NVIDIA Advanced Optimus, and enhanced camera and microphone technologies, the Predator Helios Neo 16S AI is built to handle the future of gaming, streaming, and productivity.', 320000.00, 15, 'static/images/productImage/1779094707954_Screenshot 2026-05-18 144316.png', '2026-05-18 08:58:27', '2026-05-18 08:58:27'),
                                                                                                                                    (60, 1, 'ASUS ROG Zephyrus G14 2024 GA403UV', 'Brand new factory-sealed Asus ROG Zephyrus G14 2024 GA403UV Gaming Laptop with 8000-series AMD Ryzen 9 8945HS, NVIDIA® GeForce RTX™ 4060 graphics card with 8GB of GDDR6 VRAM, 16GB DDR5 RAM , 1TB M.2 NVMe PCIe 4.0 SSD, 14-inch ROG Nebula display with 3K (2880 x 1800) OLED 16:10 aspect ratio, 120Hz refresh rate, 0.2ms response time, Pantone Validated DCI-P3: 100% color gamut, IPS panel with 16:10 aspect ratio, 4-speaker stereo audio system with Smart Amplifier Technology, Dolby Atmos support, 0.64-inch thickness, 1.5KG Weight, 2 Year Warranty, Free Asus Original Zephyrus Sleeve Case, and Gaming Mouse  and Free delivery all over Nepal', 318900.00, 14, 'static/images/productImage/1779094764853_Screenshot 2026-05-18 144412.png', '2026-05-18 08:59:24', '2026-05-18 08:59:37'),
                                                                                                                                    (61, 1, 'MSI Crosshair 16 HX AI D2XWGKG', 'The MSI Crosshair 16 HX AI D2XWGKG is a high-end gaming laptop designed for gamers, creators, and professionals who need extreme performance and next-generation AI capabilities. Powered by the Intel Core Ultra 9 275HX processor and NVIDIA GeForce RTX 5070 graphics, this laptop delivers exceptional speed, smooth gameplay, and powerful multitasking for demanding workloads.\r\n\r\nIt features a 16-inch QHD display with a 240Hz refresh rate, offering ultra-smooth visuals and sharp image clarity. The high refresh rate makes it ideal for competitive gaming, while the larger display enhances productivity and immersive viewing.\r\n\r\nWith 16GB DDR5 RAM and a 1TB NVMe Gen 4 SSD, the MSI Crosshair 16 HX AI provides fast performance, quick boot times, and ample storage for games, creative projects, and professional applications. The system also supports upgrades, making it a future-ready investment.\r\n\r\nThe NVIDIA RTX 5070 GPU brings advanced ray tracing and AI-powered features, enabling high FPS gaming, content creation, and intensive workloads. Combined with MSI’s advanced cooling system, the laptop ensures stable performance even during heavy usage.\r\n\r\nOverall, the MSI Crosshair 16 HX AI is a premium gaming laptop in Nepal, offering top-tier performance, a high refresh rate display, and powerful hardware for gaming, streaming, and professional use.\r\n\r\n', 295000.00, 11, 'static/images/productImage/1779094882527_Screenshot 2026-05-18 144610.png', '2026-05-18 09:01:22', '2026-05-18 09:01:22'),
                                                                                                                                    (62, 1, 'ASUS Zenbook S16 OLED 2024 ( UM5606WA )', 'ASUS Zenbook S16 OLED 2024 (UM5606WA) – Premium AI Laptop with Stunning OLED Display\r\nThe ASUS Zenbook S16 OLED 2024 is built for users who demand performance, portability, and a premium visual experience. Powered by the latest AMD Ryzen AI processor and paired with a vibrant 3K OLED display, this laptop is ideal for professionals, creators, and students looking for a reliable and future-ready device.\r\n\r\nPowerful Performance with AMD Ryzen AI\r\nThe AMD Ryzen AI 9 HX 370 processor delivers exceptional speed and efficiency for modern workloads. From heavy multitasking to AI-powered applications, this laptop ensures smooth and responsive performance.\r\n\r\nWith 32GB RAM, you can easily handle demanding software, multiple tabs, and creative tools without lag. The 1TB SSD provides fast boot times, quick file access, and enough space for large files, media, and projects.', 285000.00, 16, 'static/images/productImage/1779094998214_Screenshot 2026-05-18 144807.png', '2026-05-18 09:03:18', '2026-05-18 09:03:18');

